#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    vec4 color = texture(InSampler, texCoord);
    // Tagged pixels have alpha 0.5; everything else drawn has 1, and empty background 0.
    bool tagged = abs(color.a - 0.5) < 0.1;
    fragColor = tagged ? vec4(color.rgb, 1.0) : vec4(0.0, 0.0, 0.0, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(std140) uniform SamplerInfo {
    vec2 OutSize;
    vec2 InSize;
};

layout(std140) uniform BlurConfig {
    vec2 Direction;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    // 13-tap Gaussian along Direction, in texels.
    const float weights[7] = float[7](0.1585, 0.1465, 0.1156, 0.0779, 0.0448, 0.0220, 0.0092);
    vec2 step = Direction / InSize;
    vec3 sum = texture(InSampler, texCoord).rgb * weights[0];
    for (int i = 1; i < 7; i++) {
        sum += texture(InSampler, texCoord + step * float(i)).rgb * weights[i];
        sum += texture(InSampler, texCoord - step * float(i)).rgb * weights[i];
    }
    fragColor = vec4(sum, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;
uniform sampler2D GlowSampler;

layout(std140) uniform GlowConfig {
    float Strength;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    vec3 color = texture(InSampler, texCoord).rgb + texture(GlowSampler, texCoord).rgb * Strength;
    fragColor = vec4(color, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes: the same as vanilla core/screenquad (26.3) and
// core/screentriangle (26.4), shipped with the pack so it does not depend on either.
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}
